import {hearButton} from './play-media.mjs';
import {labelCases} from './exhibit-label-content.mjs';
import {labelView,labelSentence,labelSpeech,validLabelResponse,startLabel,moveLabel,wordLabel,supportLabel,askLabel,keepLabel,recoverLabels} from './exhibit-label-core.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(title,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(title)}</button>`;
const asset=s=>['egypt-writing-board-28-9-5.jpg','egypt-scribe-palette-10-176-62.jpg'].includes(s.sourceCard.assetId)?`./assets/${s.sourceCard.assetId}`:null;
function recordUrl(s){try{const u=new URL(s.sourceCard.recordUrl);return u.protocol==='https:'&&u.hostname==='www.metmuseum.org'&&!u.username&&!u.password&&!u.port&&/^\/art\/collection\/search\/\d+$/.test(u.pathname)&&!u.search&&!u.hash?u.href:null;}catch{return null;}}
const record=s=>recordUrl(s)?`<a href="${esc(recordUrl(s))}" target="_blank" rel="noopener noreferrer">Open The Met object record</a>`:`<p class="label-small">Saved record address: ${esc(s.sourceCard.recordUrl)}</p>`;
function photo(s,compact=false){const c=s.sourceCard,src=asset(s),fallback=`<div data-label-photo-fallback ${src?'hidden':''}><p>${esc(c.alt)}</p><p>${esc(c.credit)} · Object ${esc(c.objectNumber)}</p></div>`;return `<figure class="label-photo ${compact?'label-photo-small':''}">${src?`<img src="${esc(src)}" alt="${esc(c.alt)}" loading="lazy" data-label-image>`:''}${fallback}${compact?'':`<figcaption>${esc(c.credit)}</figcaption>`}</figure>`;}
function sourceFull(s){const c=s.sourceCard;return `<div class="label-source-full" data-label-source><h3>${esc(s.title)}</h3><p><strong>The Met, object ${esc(c.objectNumber)}.</strong> ${esc(c.date)}. ${esc(c.materials)}.</p>${photo(s)}<p>${esc(c.sharedNote)}</p>${record(s)}</div>`;}
function sourceSmall(s){const c=s.sourceCard;return `<aside class="label-source-small"><div>${photo(s,true)}<p><strong>${esc(s.title)}</strong><br>The Met, ${esc(c.objectNumber)}</p></div>${record(s)}<details><summary>See the full source and photo</summary>${sourceFull(s)}</details></aside>`;}
function labelLines(s,kind='current'){return `<ol class="label-lines" data-label-lines="${kind}">${s.order.map(role=>`<li data-label-line="${role}">${role==='claim'&&s.wording==='broad'?`<strong class="label-warning" data-label-warning>${esc(s.source.copy.draftWarning)}</strong>`:''}<span>${esc(labelSentence(s,role))}</span></li>`).join('')}</ol>`;}
const responseText=(r,source,current)=>`<div class="label-response" ${current?'data-label-current-response':''}><p class="label-small">${current?'Visitor response to this draft':esc(source.copy.earlierResponse)}</p><p>${esc(r.openingText)}</p><p>${esc(r.claimText)}</p></div>`;
let turn={caseId:null,explorer:null,view:'learn',frame:0,modelOpen:false};
export function resetLabelTurn(){turn={caseId:null,explorer:null,view:'learn',frame:0,modelOpen:false};}
function syncTurn(caseId,explorer){if(turn.caseId!==caseId||turn.explorer!==explorer)turn={caseId,explorer,view:caseId?'arrange':'learn',frame:0,modelOpen:false};}
function chooser(v){return `<section class="label-chooser"><h2>Choose one real object</h2><p>Both objects are open. The bookstall is a fictional doorway; these source records belong to The Met.</p>${labelCases.map(s=>{const old=v.cases.find(c=>c.id===s.id),bad=v.unreadable.some(c=>c.id===s.id);return `<article><h3>${esc(old?.work.source.title||s.title)}</h3><p>${esc(old?.work.source.readerRequest||s.readerRequest)}</p>${bad?'<p>This saved label is unreadable. Its original record stays in the download.</p>':button(old?'Open saved label':'Start this label',`data-label-start="${s.id}"`)}</article>`;}).join('')}${v.cases.filter(c=>!labelCases.some(s=>s.id===c.id)).map(c=>`<article><h3>${esc(c.work.source.title)}</h3>${button('Open earlier label',`data-label-start="${esc(c.id)}"`)}</article>`).join('')}</section>`;}
function model(w){const frames=w.source.modelFrames,step=Math.min(turn.frame,frames.length-1),frame=frames[step];return `<details class="label-model" ${turn.modelOpen?'open':''}><summary>A ready-made example, one thought at a time</summary><p>Your own order and claim stay as you left them.</p><div class="label-model-frame" data-label-model-frame><p class="label-small">Example thought ${step+1} of ${frames.length}</p><blockquote>${esc(frame.text)}</blockquote><p>${esc(frame.caption)}</p></div><div class="label-controls">${button('Previous thought',`data-label-example-step="-1" ${step===0?'disabled':''}`)}${button('Next thought',`data-label-example-step="1" ${step===frames.length-1?'disabled':''}`)}</div><details><summary>Read all the example thoughts</summary><ol>${frames.map(f=>`<li>${esc(f.text)} ${esc(f.caption)}</li>`).join('')}</ol></details></details>`;}
function learn(w){const s=w.source;return `<section data-label-view-panel="learn"><h2>Learn from this source</h2><p>For a visitor: ${esc(s.readerRequest)}</p>${sourceFull(s)}<details class="label-help"><summary>Help with the source and claim</summary><p>${esc(s.copy.help)}</p></details>${model(w)}${button('We thought together','data-label-together')}</section>`;}
function arrange(w){const s=w.source;return `<section data-label-view-panel="arrange"><h2>Arrange three sentences</h2><p class="label-reader">Our visitor asks: ${esc(s.readerRequest)}</p>${sourceSmall(s)}<p>${esc(s.copy.instruction)}</p><ol class="label-strips">${w.order.map((role,i)=>`<li data-label-strip="${role}" tabindex="-1"><div class="label-strip-head"><span class="label-position">${i+1}</span><span class="label-role">${role==='object'?'Object':role==='use'?'Use':'Claim'} sentence</span></div>${role==='claim'&&w.wording==='broad'?`<strong class="label-warning" data-label-warning>${esc(s.copy.draftWarning)}</strong>`:''}<p>${esc(labelSentence(w,role))}</p><div class="label-controls">${button('Earlier',`data-label-move="${role}" data-label-delta="-1" aria-label="Move ${role} sentence, position ${i+1}, earlier" ${i===0?'disabled':''}`)}${button('Later',`data-label-move="${role}" data-label-delta="1" aria-label="Move ${role} sentence, position ${i+1}, later" ${i===2?'disabled':''}`)}</div></li>`).join('')}</ol><fieldset><legend>What should the claim sentence say?</legend><div class="label-controls">${button('Draft claim to inspect',`data-label-wording="broad" aria-pressed="${w.wording==='broad'}"`)}${button('Careful source wording',`data-label-wording="careful" aria-pressed="${w.wording==='careful'}"`)}</div><p class="label-small">${esc(s.copy.carefulNotice)}</p></fieldset></section>`;}
function keptPanel(v){if(v.keptUnreadable)return '<p>An earlier kept label is unreadable. It stays unchanged in notes. Replace is unavailable; a separate label notebook keeps this original.</p>';if(!v.kept)return '<p>No label is kept yet. An unfinished or draft label can be kept.</p>';const k=v.kept,s=k.snapshot;return `<details class="label-kept"><summary>Read the one kept label</summary><p class="label-small">Saved version of ${esc(s.source.title)}. ${s.wording==='broad'?'Draft with a broad claim to inspect.':'Careful source wording.'}</p>${labelLines(s,'kept')}${k.response?responseText(k.response,s.source,true):'<p>This label was kept without a visitor response.</p>'}${hearButton(labelSpeech(s),'Hear the kept label').replace('<button ','<button data-label-hear="kept" ')}<p>The kept copy stays as it was, even if you change the current label.</p></details>`;}
function read(w,v){const s=w.source,initial={source:s,order:s.initialOrder,wording:s.initialWording};return `<section data-label-view-panel="read"><h2>Read and keep a label</h2><p class="label-reader">For our visitor: ${esc(s.readerRequest)}</p>${sourceSmall(s)}<section class="label-preview"><h3>Our current label</h3>${w.wording==='broad'?'<p class="label-small">Draft with a broad claim to inspect.</p>':''}${labelLines(w)}</section>${hearButton(labelSpeech(w),'Hear this label').replace('<button ','<button data-label-hear="current" ')}${button('Back to Arrange','data-label-view="arrange"')}${button('Ask our visitor to read this label','data-label-ask',true)}<div id="label-response" role="status" tabindex="-1">${v.currentResponse?responseText(v.currentResponse,s,true):v.response?responseText(v.response,s,false):v.responseUnreadable?'<p>An earlier visitor response is unreadable and remains in your download. Ask again to hear about this draft.</p>':'<p>The visitor has not read this draft yet.</p>'}</div>${v.response?hearButton(v.response.openingText+' '+v.response.claimText,v.currentResponse?'Hear this visitor response':'Hear this earlier visitor response').replace('<button ','<button data-label-hear="response" '):''}${button(v.kept===null?'Keep this label':'Replace the kept label',`data-label-keep ${v.keptUnreadable?'disabled':''}`)}${keptPanel(v)}<details class="label-initial"><summary>Compare the starting draft</summary><p class="label-small">This saved starting arrangement is a ready-made draft, not a museum’s statement.</p>${labelLines(initial,'initial')}</details><p>${esc(s.copy.humanRead)}</p><p><a href="#loft">Story Loft is for fictional storytelling, not a historical evidence submission.</a></p></section>`;}
export const labelEntry=()=>'<section class="resume-strip label-entry"><div><h2>Make a short museum label</h2><p>The book showed us two real objects. Make a short label for a visitor using The Met’s object records.</p><a class="secondary" href="#archive/labels">Open Exhibit Label Maker</a></div></section>';
export function labelPage(state,caseId=null,explorerId=null){
 syncTurn(caseId,explorerId);const v=labelView(state,caseId),head='<section class="label-sheet" data-label-root><a class="back" href="#archive">Back to Travelers’ Archive</a>',status='<p id="label-status" data-label-status role="status" tabindex="-1"></p>';
 if(v.status==='recovery')return head+'<h1 id="label-title" tabindex="-1">An earlier label notebook is kept</h1><p>It cannot be read here. The complete original stays in your notes download.</p>'+button('Start a separate label notebook','data-label-recover')+status+'<a href="#notes">Grown-up notes and download</a></section>';
 if(!v.selected)return head+'<h1 id="label-title" tabindex="-1">Exhibit Label Maker</h1><p>Arrange source-backed sentences for a visitor. More than one order can make sense.</p>'+chooser(v)+(caseId&&v.unreadable.some(c=>c.id===caseId)?'<p>This saved label cannot be opened; it remains in notes.</p>':'')+(v.unreadable.length?button('Start a separate label notebook','data-label-recover'):'')+status+'<a href="#notes">Grown-up notes and download</a></section>';
 const w=v.selected.work,view=turn.view;return head+`<p class="label-eyebrow">Saved source version · The Met, ${esc(w.source.sourceCard.objectNumber)}</p><h1 id="label-title" tabindex="-1">${esc(w.source.title)}</h1><nav class="label-tabs" aria-label="Label maker views">${[['learn','Learn'],['arrange','Arrange'],['read','Read & Keep']].map(([key,title])=>button(title,`data-label-view="${key}" aria-current="${view===key?'page':'false'}"`)).join('')}</nav>${status}${view==='learn'?learn(w):view==='arrange'?arrange(w):read(w,v.selected)}<p class="label-small">This is one saved source version. The app can describe a ready-made label; a person can read your own words.</p><details class="label-more"><summary>Other labels and grown-up notes</summary>${chooser(v)}<p><a href="#notes">Grown-up notes and download</a></p>${button('Start a separate label notebook','data-label-recover')}</details></section>`;
}
export function labelNotes(state){const v=labelView(state);if(v.status==='missing')return '';if(v.status==='recovery')return '<section class="panel"><h2>Exhibit labels</h2><p>An unreadable earlier label notebook remains in the JSON download.</p></section>';return `<details class="panel"><summary>Exhibit labels: saved source-backed drafts</summary><p>Supplied sentences and visitor lines are not independent prose assessment. Full sources and raw siblings remain in the JSON download.</p>${v.cases.map(c=>{const w=c.work,count=Array.isArray(w.earlierRawResponses)?w.earlierRawResponses.length:0,badHistory=Object.hasOwn(w,'earlierRawResponses')&&!Array.isArray(w.earlierRawResponses);return `<section><h3>${esc(w.source.title)}</h3><p>Source version: The Met, ${esc(w.source.sourceCard.objectNumber)}. Support: ${esc(w.support.join(', ')||'none recorded')}.</p>${labelLines(w)}${c.response?responseText(c.response,w.source,!!c.currentResponse):''}${c.kept?`<h4>Kept label</h4>${labelLines(c.kept.snapshot,'kept')}${c.kept.response?responseText(c.kept.response,c.kept.snapshot.source,true):''}`:''}${c.responseUnreadable||c.keptUnreadable||count||badHistory?`<p>Unreadable earlier material is retained unchanged in the download (${count} earlier raw responses${badHistory?'; one unreadable response-history slot':''}).</p>`:''}</section>`;}).join('')}${v.unreadable.length?'<p>Some saved labels are unreadable; their exact records remain in the JSON download.</p>':''}</details>`;}
export function bindLabel(state,{save,render,navigate,focus,canExport,explorerId}){
 const scope=document.querySelector('[data-label-root]');if(!scope)return;
 const route=location.hash,explorer=explorerId(),caseId=route.slice(1).split('/')[2]||null;
 const live=b=>scope.isConnected&&b.isConnected&&scope.contains(b)&&location.hash===route&&explorerId()===explorer;
 const msg=t=>{const n=scope.querySelector('[data-label-status]');if(n)n.textContent=t;};
 const refusal='This change could not fit safely. Earlier work stays unchanged. Download notes, or use a separate explorer if this notebook is full.';
 const refuse=(t=refusal)=>{msg(t);focus('#label-status');return false;};
 const run=(fn,target='#label-title',successMessage='')=>{if(!live(scope))return false;if(!fn())return refuse();save();render();if(successMessage)document.querySelector('#label-status').textContent=successMessage;focus(target);return true;};
 const click=(sel,fn)=>scope.querySelectorAll(sel).forEach(b=>b.addEventListener('click',e=>{if(live(b))fn(b,e);}));
 const useSupport=(code,e)=>{if(!live(scope)){e?.stopImmediatePropagation();return false;}if(!supportLabel(state,caseId,code,canExport)){refuse();e?.stopImmediatePropagation();return false;}save();return true;};
 const confirm=(recovery,action)=>{if(!live(scope))return;const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${recovery?'Start a separate label notebook?':'Replace the one kept label?'}</h2><p>${recovery?'The entire earlier label notebook, including its prior recovery copy, stays in your download.':'The one earlier kept label will be replaced.'} Download notes first if you want another copy.</p><button type="button" class="secondary" data-label-cancel>Keep this page</button><button type="button" class="primary" data-label-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-label-cancel]').onclick=()=>d.close();d.querySelector('[data-label-confirm]').onclick=()=>{if(!d.isConnected||!d.open||!live(scope))return;d.close();run(action);};d.addEventListener('close',()=>d.remove());};
 click('[data-label-start]',b=>{const key=b.dataset.labelStart;if(!startLabel(state,key,canExport))return refuse();save();turn={caseId:key,explorer,view:'learn',frame:0,modelOpen:false};navigate('#archive/labels/'+key);});
 click('[data-label-view]',b=>{turn.view=b.dataset.labelView;render();focus(`[data-label-view="${turn.view}"]`);});
 click('[data-label-move]',b=>{const role=b.dataset.labelMove,delta=Number(b.dataset.labelDelta);if(run(()=>moveLabel(state,caseId,role,delta,canExport),`[data-label-strip="${role}"]`)){const chosen=`[data-label-move="${role}"][data-label-delta="${delta}"]`,other=`[data-label-move="${role}"][data-label-delta="${-delta}"]`;focus(document.querySelector(chosen)?.disabled?other:chosen);}});
 click('[data-label-wording]',b=>run(()=>wordLabel(state,caseId,b.dataset.labelWording,canExport),`[data-label-wording="${b.dataset.labelWording}"]`));
 click('[data-label-ask]',()=>{const v=labelView(state,caseId).selected,w=v?.work;if(v?.responseUnreadable&&Object.hasOwn(w,'earlierRawResponses')&&!Array.isArray(w.earlierRawResponses))return refuse('An earlier response-history slot is unreadable. It stays in your notes; use a separate label notebook before asking again.');run(()=>askLabel(state,caseId,canExport),'#label-response');});
 click('[data-label-keep]',()=>{const v=labelView(state,caseId).selected;if(v?.keptUnreadable)return refuse('The earlier kept label remains unchanged in notes. Start a separate label notebook to keep another version.');if(v?.work.kept!==null)confirm(false,()=>keepLabel(state,caseId,true,canExport));else run(()=>keepLabel(state,caseId,false,canExport),'#label-status','This label is kept.');});
 click('[data-label-recover]',()=>confirm(true,()=>recoverLabels(state,canExport)));
 click('[data-label-together]',(_b,e)=>{if(useSupport('together',e))msg('Thinking together is recorded.');});
 scope.querySelector('.label-help')?.addEventListener('toggle',e=>{if(e.target.open&&!useSupport('help',e))e.target.open=false;});
 scope.querySelector('.label-model')?.addEventListener('toggle',e=>{turn.modelOpen=e.target.open;if(e.target.open&&!useSupport('example',e)){turn.modelOpen=false;e.target.open=false;}});
 click('[data-label-example-step]',(b,e)=>{if(!useSupport('example',e))return;const n=labelView(state,caseId).selected?.work.source.modelFrames.length||0;turn.frame=Math.max(0,Math.min(n-1,turn.frame+Number(b.dataset.labelExampleStep)));turn.modelOpen=true;render();focus('[data-label-model-frame]');});
 scope.querySelectorAll('[data-label-hear]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.stopImmediatePropagation();return;}const v=labelView(state,caseId).selected;if(!v||!useSupport('narrationRequested',e))return;const kind=b.dataset.labelHear;b.dataset.speak=kind==='kept'&&v.kept?labelSpeech(v.kept.snapshot):kind==='response'&&v.response?v.response.openingText+' '+v.response.claimText:labelSpeech(v.work);}))
 scope.querySelectorAll('[data-label-image]').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.nextElementSibling?.removeAttribute('hidden');}));
}
